    return t2 * llabs(x1 - x2);
}

long long tram(long long p, long long x2, long long x1,
               long long t1, int d, long long s) {
    long long distance = 0;

    if (x2 > x1) {
        if (d == 1 && p <= x1)
            distance = x2 - p;
        else if (d == 1)
            distance = 2 * s - p + x2;
        else
            distance = p + x2;
