#include <iostream>
#include <algorithm>
#include <cstdlib>

using namespace std;

long long tramTime(long long s, long long x1, long long x2,
                   long long t1, long long p, int d) {
    long long distance = 0;

    if (d == 1) {
        if (p <= x1) {
            distance = x1 - p;
        } else {
            distance = (s - p) + (s - x1);
            d = -1;
        }
    } else {
        if (p >= x1) {
            distance = p - x1;
        } else {
            distance = p + x1;
            d = 1;
        }
    }

    if (d == 1) {
        distance += (x2 >= x1) ? x2 - x1 : (s - x1) + (s - x2);
    } else {
        distance += (x2 <= x1) ? x1 - x2 : x1 + x2;
    }

    return distance * t1;
}

int main() {
    long long s, x1, x2, t1, t2, p;
    int d;

    cin >> s >> x1 >> x2;
    cin >> t1 >> t2;
    cin >> p >> d;

    long long walkingTime = llabs(x1 - x2) * t2;
    long long answer = min(walkingTime, tramTime(s, x1, x2, t1, p, d));

    cout << answer;
    return 0;
}

